{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is undocumented; silence does not establish whether it occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score provides no evidence of consistency across runs."
        }
      ],
      "instrument_review": "Construction and scoring are described for a narrow grid-puzzle comparison. The 70% result describes the reported run, but repeatability and variation are unknown. Fair comparison would require sufficient reporting of evaluation conditions."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "A single evaluation cannot establish consistency across runs; it also does not demonstrate instability."
        }
      ],
      "instrument_review": "The puzzle set and exact-grid scoring support interpreting the reported score within the stated task. Lack of repeated testing is documented, leaving score consistency unassessed and limiting confidence in comparisons based on that run."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The report explicitly describes repeated evaluations under unchanged conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stability: at most two percentage points."
        }
      ],
      "instrument_review": "Repeated testing with specified controls supports consistency under these conditions and the stated stability definition. This strengthens interpretation of the grid-puzzle score, but does not establish consistency under different conditions or performance on other tasks."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers explicitly tested repeated runs with the listed conditions held constant."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed variation exceeds the report's stability limit of two percentage points."
        }
      ],
      "instrument_review": "The controlled repeats document a consistency problem under the report's own criterion. The isolated 70% score should therefore not be presented as stable performance. Comparisons need to account for the reported variation; its cause is not supplied."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation documentation does not establish that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The new instructions provide no evidence about score variation across runs."
        }
      ],
      "instrument_review": "Installation instructions explain setup, but add no findings about consistency or comparison quality. The reported score remains evidence about one run on the grid puzzles; repeated-run behavior and sufficiently matched comparison conditions remain unestablished."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the reported conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "The evaluated content, exact-grid scoring, and fixed instructions support the intended narrow comparison. Repeated-run consistency and other resource or setting controls are not reported. The observed ranking should remain limited to the evaluated puzzles and conditions."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results show better performance by A on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A stated intention to select for general intelligence does not supply evidence across domains."
        }
      ],
      "instrument_review": "The intended use exceeds the supplied evidence: a grid-puzzle ranking does not establish a general-intelligence ranking across domains. Exact scoring and fixed instructions clarify the narrow comparison, while broader task coverage, consistency, and other comparison controls remain undocumented."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone provide no supplied evidence that A improves actual workshop decisions compared with B."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports higher correctness with A in the studied workshop; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Decision correctness does not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "The later trial adds evidence directly relevant to the intended workshop use. Preregistration, random allocation, new cases, blinded correctness checking, and reported uncertainty strengthen the comparison. Its support is limited to correctness in the studied workshop and conditions; safety, time, and transfer to other workshops are unestablished."
    }
  ],
  "closing_note": "No material instruction ambiguity was identified. Missing evidence was distinguished from explicit conflict, and intended uses were assessed separately from what the findings support."
}
